#define ADC_CFG_GNDSEL_Pos                (28UL)                    /*!< GNDSEL (Bit 28)                                       */
#define ADC_CFG_GNDSEL_Msk                (0x70000000UL)            /*!< GNDSEL (Bitfield-Mask: 0x07)                          */
